func TestNoUselessSpreadCollectionConstructor(t *testing.T) {
	rule_tester.RunRuleTester(fixtures.GetRootDir(), "tsconfig.json", t, &no_useless_spread.NoUselessSpreadRule,
		[]rule_tester.ValidTestCase{
			{Code: "new Set(iterable)", FileName: "file.js"},
			{Code: "new NotSet(...iterable)", FileName: "file.js"},
			{Code: "new namespace.Set(...iterable)", FileName: "file.js"},
			{Code: "Set(...iterable)", FileName: "file.js"},
			{Code: "new Uint8Array(...iterable)", FileName: "file.js"},
			{Code: "new Set(...iterable, extraArgument)", FileName: "file.js"},
		},
		[]rule_tester.InvalidTestCase{
			{Code: "new Set(...iterable)", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-collection-constructor", Message: "`new Set(…)` accepts a single iterable argument, spreading is misleading.", Line: 1, Column: 9, EndLine: 1, EndColumn: 20}}},
			{Code: "new Map(...iterable)", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-collection-constructor", Message: "`new Map(…)` accepts a single iterable argument, spreading is misleading.", Line: 1, Column: 9, EndLine: 1, EndColumn: 20}}},
			{Code: "new WeakSet(...iterable)", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-collection-constructor", Message: "`new WeakSet(…)` accepts a single iterable argument, spreading is misleading.", Line: 1, Column: 13, EndLine: 1, EndColumn: 24}}},
			{Code: "new WeakMap(...iterable)", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-collection-constructor", Message: "`new WeakMap(…)` accepts a single iterable argument, spreading is misleading.", Line: 1, Column: 13, EndLine: 1, EndColumn: 24}}},
			{Code: "new Set(...getNames())", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-collection-constructor", Message: "`new Set(…)` accepts a single iterable argument, spreading is misleading.", Line: 1, Column: 9, EndLine: 1, EndColumn: 22}}},
		})
}

