func TestNoUselessSpreadTypeScript(t *testing.T) {
	rule_tester.RunRuleTester(fixtures.GetRootDir(), "tsconfig.json", t, &no_useless_spread.NoUselessSpreadRule,
		[]rule_tester.ValidTestCase{},
		[]rule_tester.InvalidTestCase{
			{Code: "for (const foo of[...iterable2]);", FileName: "file.ts", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "iterable-to-array-in-for-of", Message: "`for…of` can iterate directly when an array snapshot is not needed.", Line: 1, Column: 18, EndLine: 1, EndColumn: 32, Suggestions: []rule_tester.InvalidTestCaseSuggestion{{MessageId: "suggestion/remove-iterable-to-array", Output: "for (const foo of iterable2);"}}}}},
		})
}

