func TestNoUselessSpreadDocumentation(t *testing.T) {
	rule_tester.RunRuleTester(fixtures.GetRootDir(), "tsconfig.json", t, &no_useless_spread.NoUselessSpreadRule,
		[]rule_tester.ValidTestCase{
			{Code: "const array = [firstElement, secondElement, thirdElement];", FileName: "file.js"},
			{Code: "const object = {firstProperty, secondProperty, thirdProperty};", FileName: "file.js"},
			{Code: "foo(firstArgument, secondArgument, thirdArgument);", FileName: "file.js"},
			{Code: "const object = new Foo(firstArgument, secondArgument, thirdArgument);", FileName: "file.js"},
			{Code: "Object.assign(target, source);", FileName: "file.js"},
			{Code: "const set = new Set(iterable);", FileName: "file.js"},
			{Code: "const results = await Promise.all(iterable);", FileName: "file.js"},
			{Code: "for (const foo of set);", FileName: "file.js"},
			{Code: "function * foo() {\n\tyield * anotherGenerator();\n}", FileName: "file.js"},
			{Code: "const array = [...foo, bar];", FileName: "file.js"},
			{Code: "const object = {...foo, bar};", FileName: "file.js"},
			{Code: "foo(foo, ...bar);", FileName: "file.js"},
			{Code: "const object = new Foo(...foo, bar);", FileName: "file.js"},
			{Code: "new Uint8Array([...'ab'])", FileName: "file.js"},
			{Code: "new Uint8Array('ab')", FileName: "file.js"},
		},
		[]rule_tester.InvalidTestCase{
			{Code: "const array = [firstElement, ...[secondElement], thirdElement];", FileName: "file.js", Output: []string{"const array = [firstElement, secondElement, thirdElement];"}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-list", Message: "Spread an array literal in array literal is unnecessary.", Line: 1, Column: 30, EndLine: 1, EndColumn: 33}}},
			{Code: "const object = {firstProperty, ...{secondProperty}, thirdProperty};", FileName: "file.js", Output: []string{"const object = {firstProperty, secondProperty, thirdProperty};"}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-list", Message: "Spread an object literal in object literal is unnecessary.", Line: 1, Column: 32, EndLine: 1, EndColumn: 35}}},
			{Code: "foo(firstArgument, ...[secondArgument], thirdArgument);", FileName: "file.js", Output: []string{"foo(firstArgument, secondArgument, thirdArgument);"}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-list", Message: "Spread an array literal in arguments is unnecessary.", Line: 1, Column: 20, EndLine: 1, EndColumn: 23}}},
			{Code: "const object = new Foo(firstArgument, ...[secondArgument], thirdArgument);", FileName: "file.js", Output: []string{"const object = new Foo(firstArgument, secondArgument, thirdArgument);"}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-list", Message: "Spread an array literal in arguments is unnecessary.", Line: 1, Column: 39, EndLine: 1, EndColumn: 42}}},
			{Code: "Object.assign(target, {...source});", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-object-assign", Message: "`Object.assign(…)` source object with only spread properties is unnecessary.", Line: 1, Column: 24, EndLine: 1, EndColumn: 27, Suggestions: []rule_tester.InvalidTestCaseSuggestion{{MessageId: "suggestion/remove-object-assign-spread", Output: "Object.assign(target, source);"}}}}},
			{Code: "const set = new Set([...iterable]);", FileName: "file.js", Output: []string{"const set = new Set(iterable);"}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "iterable-to-array", Message: "`new Set(…)` accepts an iterable as an argument, it's unnecessary to convert to an array.", Line: 1, Column: 21, EndLine: 1, EndColumn: 34}}},
			{Code: "const set = new Set(...iterable);", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "spread-in-collection-constructor", Message: "`new Set(…)` accepts a single iterable argument, spreading is misleading.", Line: 1, Column: 21, EndLine: 1, EndColumn: 32}}},
			{Code: "const results = await Promise.all([...iterable]);", FileName: "file.js", Output: []string{"const results = await Promise.all(iterable);"}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "iterable-to-array", Message: "`Promise.all(…)` accepts an iterable as an argument, it's unnecessary to convert to an array.", Line: 1, Column: 35, EndLine: 1, EndColumn: 48}}},
			{Code: "for (const foo of [...set]);", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "iterable-to-array-in-for-of", Message: "`for…of` can iterate directly when an array snapshot is not needed.", Line: 1, Column: 19, EndLine: 1, EndColumn: 27, Suggestions: []rule_tester.InvalidTestCaseSuggestion{{MessageId: "suggestion/remove-iterable-to-array", Output: "for (const foo of set);"}}}}},
			{Code: "function * foo() {\n\tyield * [...anotherGenerator()];\n}", FileName: "file.js", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "iterable-to-array-in-yield-star", Message: "`yield*` can delegate directly when materializing the iterable is unnecessary.", Line: 2, Column: 10, EndLine: 2, EndColumn: 33, Suggestions: []rule_tester.InvalidTestCaseSuggestion{{MessageId: "suggestion/remove-iterable-to-array", Output: "function * foo() {\n\tyield * anotherGenerator();\n}"}}}}},
		})
}
